describe('the websocket frame validator', () => {
  it('accepts user_message and returns the frame the exported union describes', () => {
    const result = validateMessage({type: 'user_message', content: 'hello'});

    expect(result).toEqual({valid: true, data: {type: 'user_message', content: 'hello'}});
  });

  it('rejects send_message, which is no longer a wire name', () => {
    const result = validateMessage({type: 'send_message', content: 'hello'});

    expect(result).toEqual({valid: false, error: 'Unknown message type: send_message'});
  });

  it('drops any field the frame does not define, rather than forwarding it', () => {
    const result = validateMessage({type: 'user_message', content: 'hello', chatId: 'c1'});

    expect(result).toEqual({valid: true, data: {type: 'user_message', content: 'hello'}});
  });

  it('accepts list_sessions and forwards its pagination fields', () => {
    expect(
      validateMessage({
        type: 'list_sessions',
        limit: 10,
        before: {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: 's1'},
        userId: 'another-user',
      })
    ).toEqual({
      valid: true,
      data: {type: 'list_sessions', limit: 10, before: {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: 's1'}},
    });
  });

  it('rejects malformed list_sessions pagination fields by name', () => {
    expect([
      validateMessage({type: 'list_sessions', limit: -1}),
      validateMessage({type: 'list_sessions', limit: 1.5}),
      validateMessage({type: 'list_sessions', limit: '10'}),
      validateMessage({type: 'list_sessions', before: 'not-an-object'}),
      validateMessage({type: 'list_sessions', before: {updatedAt: 'not-a-date', sessionId: 's1'}}),
      validateMessage({type: 'list_sessions', before: {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: ''}}),
    ]).toEqual([
      {valid: false, error: expect.stringContaining('limit')},
      {valid: false, error: expect.stringContaining('limit')},
      {valid: false, error: expect.stringContaining('limit')},
      {valid: false, error: expect.stringContaining('before')},
      {valid: false, error: expect.stringContaining('before')},
      {valid: false, error: expect.stringContaining('before')},
    ]);
  });

  it('accepts a list_conversations frame with an ISO cursor', () => {
    expect(
      validateMessage({
        type: 'list_conversations',
        limit: 10,
        before: {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: 's1'},
        userId: 'another-user',
      })
    ).toEqual({
      valid: true,
      data: {type: 'list_conversations', limit: 10, before: {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: 's1'}},
    });
  });

  it('rejects zero list_sessions limit because pagination limits start at one', () => {
    expect(validateMessage({type: 'list_sessions', limit: 0})).toEqual({
      valid: false,
      error: expect.stringContaining('limit'),
    });
  });

  it('accepts a finite numeric updatedAt in a list_sessions cursor', () => {
    expect(validateMessage({type: 'list_sessions', before: {updatedAt: 1767225600000, sessionId: 's1'}})).toEqual({
      valid: true,
      data: {type: 'list_sessions', before: {updatedAt: 1767225600000, sessionId: 's1'}},
    });
  });
});
import type {SessionEntry} from './session.js';
import type {SessionCursor, SessionSummary} from './sessionStore.js';

export interface UserMessagePayload {
  type: 'user_message';
  content: string;
}

export interface PingMessage {
  type: 'ping';
  timestamp: number;
}

export interface ListSessionsMessage {
  type: 'list_sessions';
  limit?: number;
  before?: SessionCursor;
}

export interface ConversationCursor {
  updatedAt: string;
  sessionId: string;
}

export interface ListConversationsMessage {
  type: 'list_conversations';
  limit?: number;
  before?: ConversationCursor;
}

export type IncomingMessage = UserMessagePayload | PingMessage | ListSessionsMessage | ListConversationsMessage;

export interface ConnectedMessage {
  type: 'connected';
  sessionId: string;
  message: string;
  examplePrompts: string[];
  resumed?: boolean;
  entryCount?: number;
  /** Why a named id was not rejoined: `expired` only for the session's own owner, `unknown` for every other case. */
  resumeFailure?: 'expired' | 'unknown';
}

export interface EntryUpsertMessage {
  type: 'entry_upsert';
  index: number;
  entry: SessionEntry;
}

export interface EntryDeltaMessage {
  type: 'entry_delta';
  index: number;
  delta: string;
}

export interface EntryCommitMessage {
  type: 'entry_commit';
  index: number;
}

export interface ErrorMessage {
  type: 'error';
  code: string;
  message: string;
}

export interface PongMessage {
  type: 'pong';
  timestamp: number;
}

export interface EntrySkipMessage {
  type: 'entry_skip';
  index: number;
}

export interface StreamEndMessage {
  type: 'stream_end';
}

export interface SessionSummaryFrame extends Omit<SessionSummary, 'createdAt' | 'updatedAt'> {
  createdAt: string;
  updatedAt: string;
}

export interface SessionListMessage {
  type: 'session_list';
  sessions: SessionSummaryFrame[];
}

export interface ConversationSummary extends Omit<SessionSummary, 'createdAt' | 'updatedAt'> {
  createdAt: string;
  updatedAt: string;
}

export interface ConversationListMessage {
  type: 'conversation_list';
  conversations: ConversationSummary[];
}

export type OutgoingMessage =
  | ConnectedMessage
  | EntryUpsertMessage
  | EntryDeltaMessage
  | EntryCommitMessage
  | EntrySkipMessage
  | ErrorMessage
  | PongMessage
  | StreamEndMessage
  | SessionListMessage
  | ConversationListMessage;

